<script setup>
import {ref,onMounted} from 'vue'
import WorkspaceLayout from '../components/WorkspaceLayout.vue'
import {api,errorMessage} from '../workspace-api'
const tools=ref([]),selected=ref(null),argumentsText=ref('{}'),error=ref(''),busy=ref(false),result=ref(null),history=ref([])
async function refresh(){try{tools.value=(await api.get('/ai/mcp')).data.tools;history.value=(await api.get('/ai/mcp/history')).data;if(!selected.value&&tools.value.length)choose(tools.value[0])}catch(e){error.value=errorMessage(e)}}
function choose(tool){selected.value=tool;result.value=null;argumentsText.value=JSON.stringify(tool.name.endsWith('currentTime')?{timezone:'Asia/Shanghai'}:tool.name.endsWith('readKnowledgeDocument')?{filename:'恋爱常见问题和回答 - 已婚篇.md'}:{},null,2)}
async function run(){error.value='';result.value=null;let args;try{args=JSON.parse(argumentsText.value)}catch{error.value='请输入合法的 JSON 参数';return}busy.value=true;try{result.value=(await api.post('/ai/mcp/call',{name:selected.value.name,arguments:args})).data;await refresh()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(refresh)
</script>
<template><WorkspaceLayout title="MCP 工具" description="查看已发现的工具，直接测试调用，检查真实返回结果。"><div v-if="error" class="error" role="alert">{{error}}</div><div class="notice">当前连接：内置知识文档与时间服务。已发现 {{tools.length}} 个工具；运行测试可确认当前连通性。Pexels 搜图需要配置 API Key。此页仅开放无副作用的知识库和时间工具测试。</div><div class="workspace-grid"><aside class="panel"><div class="row"><h2>可用工具</h2><button class="secondary" @click="refresh" :disabled="busy">刷新</button></div><button v-for="tool in tools" :key="tool.name" class="item" :class="{active:selected?.name===tool.name}" :disabled="busy" @click="choose(tool)">{{tool.name.replace('yangbin_ai_agent_knowledge_','')}}<span>{{tool.description}}</span></button><p v-if="!tools.length" class="muted">未发现工具，请检查 MCP 服务是否启用。</p></aside><div><section v-if="selected" class="panel"><h2 style="overflow-wrap:anywhere">{{selected.name.replace('yangbin_ai_agent_knowledge_','')}}</h2><p>{{selected.description}}</p><details><summary>参数定义</summary><pre>{{JSON.stringify(JSON.parse(selected.schema),null,2)}}</pre></details><form @submit.prevent="run"><label>调用参数（JSON）<textarea v-model="argumentsText" spellcheck="false" :disabled="busy" style="font-family:monospace;min-height:140px"></textarea></label><button :disabled="busy||!selected.testable">{{busy?'工具执行中…':'运行测试'}}</button></form><div v-if="result" style="margin-top:22px"><div class="row"><span class="badge" :class="{failed:!result.success}">{{result.success?'调用成功':'调用失败'}}</span><span class="muted">{{result.durationMs}} ms</span></div><pre style="margin-top:12px">{{result.result}}</pre></div></section><section class="panel"><h2>最近测试记录</h2><p class="muted">保留最近 50 次手动测试，重启后清空。聊天中的执行记录显示在对应聊天页。</p><details v-for="item in history" :key="item.id"><summary>{{item.success?'成功':'失败'}} · {{item.name.replace('yangbin_ai_agent_knowledge_','')}} · {{item.durationMs}} ms</summary><p class="muted">{{new Date(item.time).toLocaleString()}}</p><pre>{{JSON.stringify(item.arguments,null,2)}}
{{item.result}}</pre></details><p v-if="!history.length" class="muted" style="margin-top:16px">还没有测试记录</p></section></div></div></WorkspaceLayout></template>